insert into public.reference_materials (material_id, material_code, department, category_code, canonical_name, base_unit, specifications, active)
select material_id, material_code, department, category_code, canonical_name, base_unit, specifications, true from _gcm_materials
on conflict (material_code) do update set
  department = excluded.department, category_code = excluded.category_code, canonical_name = excluded.canonical_name,
